import { useState } from 'react';

function Counter() {
 const [count, setCount] = useState(0); // 0 is initial

 return (
 <div>
 <p>You clicked {count} times</p>
 <button onClick={() => setCount(count + 1)}>Click +1</button>
 <button onClick={() => setCount(count - 1)}>Click -1</button>
 <button onClick={() => setCount(0)}>Reset</button>
 </div>
 );
}

