import { useState } from 'react';

function LessonTracker() {
 const [completed, setCompleted] = useState(2); // 2 lessons completed
 const total = 10;
 const progress = (completed / total) * 100;

 function completeLesson() {
 if (completed < total) {
 setCompleted(completed + 1); // Change state!
 }
 }

 return (
 <div style={{background: '#07111f', color: 'white', padding: '20px'}}>
 <p>Course Progress: {completed}/{total} - {progress}%</p>
 <div style={{background: 'gray', height: '9px', borderRadius: '99px'}}>
 <div style={{width: `${progress}%`, height: '100%', background: 'linear-gradient(90deg, #61dafb, #8b5cf6)', borderRadius: '99px'}}></div>
 </div>
 <button onClick={completeLesson} style={{marginTop: '15px', padding: '10px'}}>Complete Next Lesson</button>
 </div>
 );
}
