function WrongCounter() {
 let count = 0; // Normal variable - React doesn't watch it
 function handleClick() {
 count++; // Changes variable but UI never updates!
 console.log(count); // Console shows 1,2,3 but UI still shows 0
 }
 return <button onClick={handleClick}>Count: {count}</button>;
}

function CorrectCounter() {
 const [count, setCount] = useState(0); // State - React watches it
 function handleClick() {
 setCount(count + 1); // Tell React to re-render!
 }
 return <button onClick={handleClick}>Count: {count}</button>;
 // Click: UI 0->1->2 updates! Because setCount triggers re-render
}

