import { useState } from 'react';

function LessonCard({ id, title, status, onComplete }) {
 return (
 <div style={{border: '1px solid gray', padding: '10px', margin: '5px'}}>
 <p>{title} - {status}</p>
 {status === 'current' && (
 <button onClick={() => onComplete(id)}>Mark Completed</button>
 )}
 </div>
 );
}

function App() {
 const [lessons, setLessons] = useState([
 {id: 1, title: "Intro", status: "completed"},
 {id: 2, title: "JSX", status: "current"},
 {id: 3, title: "Props", status: "locked"},
 ]);
 const completed = lessons.filter(l => l.status === 'completed').length;

 function handleComplete(id) {
 setLessons(lessons.map(l => 
 l.id === id? {...l, status: 'completed'} : 
 l.id === id + 1? {...l, status: 'current'} : l
 ));
 }

 return (
 <div>
 <h2>Progress: {completed}/{lessons.length}</h2>
 {lessons.map(lesson => (
 <LessonCard key={lesson.id} {...lesson} onComplete={handleComplete} />
 ))}
 </div>
 );
}
