import { useState } from 'react';

function LessonCard({ id, title, learn, status, onComplete }) {
 const isLocked = status === 'locked';
 const badgeColor = status === 'completed'? '#22c55e' : status === 'current'? '#61dafb' : '#94a3b8';
 return (
 <div style={{background: 'rgba(15,31,51,0.82)', border: `1px solid ${badgeColor}30`, borderRadius: '20px', padding: '22px', opacity: isLocked? 0.58 : 1}}>
 <div style={{display: 'flex', justifyContent: 'space-between'}}>
 <span style={{color: '#61dafb', fontSize: '11px', fontWeight: '800'}}>LESSON {String(id).padStart(2,'0')}</span>
 <span style={{color: badgeColor, background: badgeColor+'1A', padding: '5px 8px', borderRadius: '999px', fontSize: '10px'}}>{status.toUpperCase()}</span>
 </div>
 <h3 style={{color: 'white', margin: '10px 0'}}>{title}</h3>
 <p style={{color: '#94a3b8', fontSize: '13px'}}>{learn}</p>
 {!isLocked? (
 <button onClick={() => onComplete(id)} style={{background: status==='completed'? '#22c55e20' : 'linear-gradient(135deg, #61dafb, #0ea5e9)', color: status==='completed'? '#4ade80' : '#06121d', border: 'none', borderRadius: '11px', padding: '10px 15px', fontWeight: '800', marginTop: '12px', cursor: 'pointer'}}>
 {status==='completed'? '✓ Completed' : 'Start → Complete'}
 </button>
 ) : (
 <button disabled style={{background: 'rgba(71,85,105,0.45)', color: '#cbd5e1', border: 'none', borderRadius: '11px', padding: '10px 15px', marginTop: '12px'}}>🔒 Locked</button>
 )}
 </div>
 );
}

function App() {
 const [lessons, setLessons] = useState([
 {id: 1, title: "Introduction to React", learn: "Understand React ecosystem", status: "completed"},
 {id: 2, title: "JSX and Components", learn: "Create reusable components", status: "completed"},
 {id: 3, title: "Props and Communication", learn: "Pass data between components", status: "completed"},
 {id: 4, title: "State and Interaction", learn: "Make UI interactive with state", status: "current"},
 {id: 5, title: "React Hooks", learn: "Use powerful hooks", status: "locked"},
 ]);
 const [xp, setXp] = useState(150);
 const [coins, setCoins] = useState(30);

 const completed = lessons.filter(l => l.status==='completed').length;
 const progress = (completed / lessons.length) * 100;

 function handleComplete(id) {
 if (lessons.find(l => l.id===id).status==='completed') return;
 setLessons(lessons.map(l => {
 if (l.id===id) return {...l, status: 'completed'};
 if (l.id===id+1 && l.status==='locked') return {...l, status: 'current'};
 return l;
 }));
 setXp(xp + 50);
 setCoins(coins + 10);
 }

 return (
 <div style={{background: '#07111f', minHeight: '100vh', padding: '20px', color: 'white'}}>
 <div style={{display: 'flex', gap: '10px', marginBottom: '20px'}}>
 <span style={{background: 'rgba(15,23,42,0.72)', padding: '9px 12px', borderRadius: '12px'}}>⚡ {xp} XP</span>
 <span style={{background: 'rgba(15,23,42,0.72)', padding: '9px 12px', borderRadius: '12px'}}>🪙 {coins}</span>
 <span style={{color: '#94a3b8', padding: '9px'}}>{completed}/{lessons.length} completed - {Math.round(progress)}%</span>
 </div>
 <div style={{height: '9px', background: 'rgba(148,163,184,0.12)', borderRadius: '99px', marginBottom: '20px'}}>
 <div style={{width: `${progress}%`, height: '100%', background: 'linear-gradient(90deg, #61dafb, #8b5cf6)', borderRadius: '99px', transition: 'width 0.6s ease'}}></div>
 </div>
 <div style={{display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '18px'}}>
 {lessons.map(lesson => <LessonCard key={lesson.id} {...lesson} onComplete={handleComplete} />)}
 </div>
 </div>
 );
}
export default App;
